using HRIS.Api.Controllers; using HRIS.Api.DTOs.Letter; using HRIS.Api.Exceptions; using HRIS.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages;
namespace HRIS.Api.Pages.Letters; [Authorize(AuthenticationSchemes="Cookies")] public class IndexModel:PageModel { private readonly ILetterService _service; public IndexModel(ILetterService service)=>_service=service; public List<LetterTypeResponseDto> Types{get;set;}=new(); public List<LetterRequestResponseDto> Items{get;set;}=new(); public bool CanManage{get;set;} public async Task OnGetAsync(){var a=User.ToUserContext();CanManage=a.IsHrOrSupport;Types=await _service.GetTypesAsync();Items=await _service.GetRequestsAsync(a);} public async Task<IActionResult> OnPostCreateAsync(int letterTypeId,string purpose,string? destination){try{await _service.CreateAsync(new LetterRequestCreateDto{LetterTypeId=letterTypeId,Purpose=purpose,Destination=destination},User.ToUserContext());TempData["Success"]="Permintaan surat diajukan.";}catch(Exception ex)when(ex is BadRequestException or ForbiddenException or NotFoundException){TempData["Error"]=ex.Message;}return RedirectToPage();} public async Task<IActionResult> OnPostSaveTypeAsync(int id,string name,int? templateDocumentId){try{await _service.SaveTypeAsync(id,new LetterTypeCreateDto{Name=name,TemplateDocumentId=templateDocumentId},User.ToUserContext());TempData["Success"]="Jenis surat disimpan.";}catch(Exception ex)when(ex is BadRequestException or ForbiddenException or NotFoundException){TempData["Error"]=ex.Message;}return RedirectToPage();} }
